// WF-6 — dual write: swarm_log + Qdrant (E7-1, E7-2, E7-4)
// Input: full state with outcome.status, candidate, test, audit
const inp = $input.first().json;
const state = inp.state || inp;
// E7-1: tool on deploy, E7-2: failure on loop exhaustion OR audit final reject
const isTool = ['deployed','reused'].includes(state.outcome?.status) && !!state.candidate?.code;
const isFailure = state.outcome?.status === 'failed' || (state.loop?.remaining === 0 && state.audit && (!state.audit.security_pass || !state.audit.edge_case_pass));
let collection = null;
let payload = null;
let textToEmbed = '';
if (isTool) {
  collection = 'tool_store';
  // E7-4: fitness update on reuse — use matching recalled tool's fitness if available
  let fitness = 1;
  let recalledMatch = null;
  if (state.recall && state.recall.reusable_tools && state.recall.reusable_tools.length) {
    recalledMatch = state.recall.reusable_tools.find(t => t.tool_name === state.candidate?.tool_name) || state.recall.reusable_tools[0];
    const prev = recalledMatch.fitness || 1;
    fitness = prev + 1;
  }
  payload = {
    type: 'tool',
    tool_name: state.candidate.tool_name,
    code: state.candidate.code,
    description: state.candidate.description,
    input_schema: state.candidate.input_schema,
    fitness: fitness,
    goal: state.goal
  };
  textToEmbed = `${state.candidate.description} ${state.goal}`;
} else if (isFailure) {
  collection = 'problem_store';
  const lastRun = state.test?.runs?.[state.test.runs.length-1] || {};
  const objections = (state.audit?.objections||[]).map(o=>o.detail).join('; ');
  payload = {
    type: 'failure',
    goal: state.goal,
    error: lastRun.stderr || objections || state.outcome?.final_answer || 'loop exhausted',
    code_summary: (state.candidate?.code||'').slice(0,300),
    date: new Date().toISOString()
  };
  textToEmbed = `${state.goal} ${payload.error}`;
}
const row = {
  task_id: state.task_id || 'unknown',
  workflow: isTool ? 'tool_store' : (isFailure ? 'problem_store' : 'swarm_log'),
  gate: state.loop?.gate || 'audit',
  verdict: state.outcome?.status || 'unknown',
  duration_ms: 0
};
function hashStr(s){let h=0;for(let i=0;i<s.length;i++){h=((h<<5)-h)+s.charCodeAt(i);h|=0;}return Math.abs(h)%1000000000;}
let pointId;
if (isTool && recalledMatch && recalledMatch.id) {
  pointId = hashStr(String(recalledMatch.id));
} else if (isTool) {
  pointId = hashStr((state.candidate.tool_name||'') + ':' + (state.task_id||''));
} else if (isFailure) {
  pointId = hashStr((state.task_id||'') + ':' + (state.goal||'').slice(0,80));
} else {
  pointId = Math.floor(Math.random()*1000000000);
}
return [{ json: { state, collection, payload, textToEmbed, row, isTool, isFailure, pointId } }];
